```javascript
function isPrime(num) {
  if (num <= 1) {
    return false;
  }
  for (let I = 2; I <= Math.sqrt(num); i++) {
    if (num % I === 0) {
      return false;
    }
  }
  return true;
}

function isValidPrime(arr) {
  for (let I = 0; I < arr.length; i++) {
    if (!isPrime(arr[i])) {
      console.log(arr[i]);
    }
  }
}
```

To use this function, you can pass an array of 5 numbers as an argument:

```javascript
const arr = [2, 3, 5, 7, 11];
isValidPrime(arr);
